var i=`0255-kolokasi-stew`;var n=`world-0255`;var s=`CY`;var a=`western-asia`;var o=4;var r=76;var l={en:`Kolokasi Stew`,ua:`Тушковане колоказі`};var d={en:`A traditional Cyprus dish made with yellow onion, celery stalk, tomato, taro root. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Кіпр. Основні інгредієнти: жовта цибуля, стебло селери, помідор, таро. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,170,`g`],[`celery-stalk`,100,`g`],[`extra-virgin-olive-oil`,55,`ml`],[`tomato`,250,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 65 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 65 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:65,i:[[`taro-root`,750,`g`],[`pork-shoulder`,400,`g`],[`water`,650,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:2,i:[[`lemon-juice`,60,`ml`],[`parsley`,15,`g`]]}];var u={slug:i,id:n,country:`CY`,region:a,servings:4,minutes:76,title:l,text:d,steps:g};export{s as country,u as default,n as id,r as minutes,a as region,o as servings,i as slug,g as steps,d as text,l as title};